cat > tests/PostTags.test.ts <<'EOF'
import { beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'
import { resetDatabase } from '../config/database.js'
import { Post } from '../app/Models/Post.js'
import { PostTag } from '../app/Models/PostTag.js'
import { Tag } from '../app/Models/Tag.js'
import { User } from '../app/Models/User.js'

describe('post tags', () => {
  let http: TestApp
  let author: Awaited<ReturnType<typeof User.forceCreate>>

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  beforeEach(async () => {
    await resetDatabase()
    author = await User.forceCreate({ name: 'A', email: 'a@example.com', passwordHash: 'x' })
  })

  const payload = (tags?: string) => ({ title: 'T', excerpt: 'E', body: 'B', tags })

  it('creates, dedupes and edits tags', async () => {
    const csrf = await http.actingAs(author).withCsrf()
    await csrf.post('/posts', payload(' bun ,bun, webdev,')).assertRedirect()
    const post = (await Post.all())[0]
    expect((await Tag.all()).map((t) => t.name).sort()).toEqual(['bun', 'webdev'])
    expect(await PostTag.where({ postId: post.id }).count()).toBe(2)
    await csrf.put(`/posts/${post.id}`, payload('bun')).assertRedirect()
    expect(await PostTag.where({ postId: post.id }).count()).toBe(1)
    await csrf.delete(`/posts/${post.id}`).assertRedirect()
  })

  it('refuses invalid tags', async () => {
    const csrf = await http.actingAs(author).withCsrf()
    await csrf.json().post('/posts', payload('a,b,c,d,e,f')).assertUnprocessable()
    await csrf.json().post('/posts', payload('x'.repeat(31))).assertUnprocessable()
    expect(await Post.all()).toHaveLength(0)
    await csrf.post('/posts', payload('x'.repeat(30))).assertRedirect()
  })

  it('filters the list', async () => {
    const csrf = await http.actingAs(author).withCsrf()
    await csrf.post('/posts', payload('bun')).assertRedirect()
    await csrf.post('/posts', payload('')).assertRedirect()
    await http.get('/posts?tag=bun').assertOk()
    await http.get('/posts?tag=none').assertOk()
  })
})
EOF
